def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace') or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 75 and opp.get('budget', 0) >= 400:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    urgency = 0
    if hp <= 3:
        urgency += 3
    elif hp <= 5:
        urgency += 2
    elif hp <= 7:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        bid = max(92.0, highest_prev + 4.0, avg_prev + 8.0)
    elif urgency >= 4:
        bid = max(78.0, highest_prev + 2.0, avg_prev + 4.0)
    elif urgency >= 2:
        if ample_supply and highest_prev >= 80:
            bid = 24.0
        else:
            bid = max(48.0, avg_prev * 0.82, highest_prev * 0.72)
    else:
        if ample_supply:
            bid = 16.0 if rich_aggressive >= 1 else 20.0
        elif tight_supply:
            bid = max(58.0, highest_prev * 0.78)
        else:
            bid = max(30.0, avg_prev * 0.55)

    if desperate_count >= 2 and urgency >= 3:
        bid += 6.0
    elif desperate_count == 0 and ample_supply and urgency <= 1:
        bid -= 4.0

    reserve = 0.0
    if hp > 6 and no_water == 0:
        reserve = 35.0
    elif hp > 4:
        reserve = 20.0

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace (immediate reaction)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely needed today.
    # If supply is high, one unit is easier to secure; if low, we must fight more.
    # Use a conservative target bid based on competition pressure.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base aggressiveness: higher when yesterday bidding was intense.
    # David/Eric averaged ~78-83; use that signal.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        pressure = 0.7
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        pressure = 0.45
    else:
        pressure = 0.25

    # If my HP is low or I've had no water days, bid more to avoid imminent death.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    elif my_no_water_days >= 2:
        urgency = 0.6
    else:
        urgency = 0.3

    # Decide target bid.
    # When supply is high, we can bid slightly less; when low, bid more.
    # Combine pressure and urgency.
    target_multiplier = 0.45 + 0.35 * pressure + 0.25 * urgency - 0.15 * supply_ratio
    target_multiplier = max(0.25, min(0.95, target_multiplier))

    target_bid = DAILY_SALARY * target_multiplier

    # Never bid above budget.
    bid = min(my_budget, target_bid)

    # If budget is too small, still try to avoid death when urgent.
    if bid < 1e-6 and (my_hp <= 4 or my_no_water_days >= 2):
        return min(my_budget, DAILY_SALARY * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    if day_context['supply'] < 18:
        return min(my_status['budget'], max(avg_prev + 5.0, 60.0))
    return min(my_status['budget'], max(avg_prev * 0.8, 35.0))
